[TFMPageType('OrderLines', "Item Setup")]
class TFMDataSourceBlockOrderLineItemSetup extends TFMDataSourceBlock
{
    boolean					allowLocationChange;
    boolean					qtyByScan;
    boolean					qtyBarcode;
    boolean					registerExpirationDate;
    TFMActionTypes			actionType;
    TFMTableNameAndField	fromLocationField;
    TFMTableNameAndField	toLocationField;
    Description255			barcodeFormat;
    InventTransId           overrideInventTransId;
    InventDimId				overrideInventDimId;

}

