[TFMParameter(NoYes::No,"@SYS345478")]
public TFMPromptForUnit parmregisterExpirationDate(TFMPromptForUnit _registerExpirationDate = registerExpirationDate)
{
    registerExpirationDate = _registerExpirationDate;
    return registerExpirationDate;
}

[TFMParameter(NoYes::Yes,"@TFM:AllowLocationChange")]
public TFMPromptForUnit parmAllowLocationChange(TFMPromptForUnit _allowLocationChange = allowLocationChange)
{
    allowLocationChange = _allowLocationChange;
    return allowLocationChange;
}

[TFMParameter(NoYes::No,"@TFM:EnableRegisterQuantityByScan")]
public TFMPromptForUnit parmQtyByScan(TFMPromptForUnit _qtyByScan = qtyByScan)
{
    qtyByScan = _qtyByScan;
    return qtyByScan;
}

[TFMParameter(NoYes::No,"@TFM:EnableBarcodeQuantity")]
public TFMPromptForUnit parmQtyBarcode(TFMPromptForUnit _qtyBarcode = qtyBarcode)
{
    qtyBarcode = _qtyBarcode;
    return qtyBarcode;
}

[TFMParameter(TFMActionTypes::TAKE)]
public TFMTakePlaceBothEnum parmActionType(TFMTakePlaceBothEnum _actionType = actionType)
{
    actionType = _actionType;
    return actionType;
}

